import urllib.request
import urllib.error
import json
import sys

def post(data, sid=None):
    req = urllib.request.Request("http://are-sidecar:8000/mcp")
    req.add_header("Content-Type", "application/json")
    req.add_header("Accept", "application/json, text/event-stream")
    if sid:
        req.add_header("mcp-session-id", sid)
    try:
        response = urllib.request.urlopen(req, data=json.dumps(data).encode('utf-8'))
        headers = response.headers
        body = response.read().decode('utf-8')
    except urllib.error.HTTPError as e:
        headers = e.headers
        body = e.read().decode('utf-8')
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

    if not sid:
        sid = headers.get('mcp-session-id')

    if "data: " in body:
        for line in body.splitlines():
            if line.startswith("data: "):
                return sid, json.loads(line[6:])
    return sid, body

def init():
    sid, _ = post({"jsonrpc": "2.0", "id": "ping", "method": "ping"})
    post({"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {"protocolVersion": "2024-11-05", "capabilities": {}, "clientInfo": {"name": "test", "version": "1.0"}}}, sid)
    post({"jsonrpc": "2.0", "method": "notifications/initialized"}, sid)
    return sid

def call_tool(method, args={}):
    sid = init()
    _, res = post({"jsonrpc": "2.0", "id": 2, "method": "tools/call", "params": {"name": method, "arguments": args}}, sid)
    if isinstance(res, dict) and "result" in res:
        return res["result"]
    return res

if __name__ == "__main__":
    if len(sys.argv) > 1:
        method = sys.argv[1]
        args = json.loads(sys.argv[2]) if len(sys.argv) > 2 else {}
        res = call_tool(method, args)
        print(json.dumps(res, indent=2))
